class ConfCalendarioSNC extends BaseConfCalendarioSNC {

    public function setUp(){
        parent::setUp();
        
    }
    
    public static function obtenerConfCalendario($idcalendario) {
	    return Doctrine::getTable('ConfCalendarioSNC')->find($idcalendario);
    }

    public static function obtenerArrConfCalendario($idcalendario){
        return Doctrine_Query::create()
             ->from('ConfCalendarioSNC')
             ->where('idcalendario = ?', array($idcalendario))
             ->fetchArray();

    }

    public static function tieneConfCalendario($idmes, $anno){
         return Doctrine_Query::create()
                -> select('count(idcalendario) as cantidad')
                -> from('ConfCalendarioSNC')
                -> where('idmes = ? and anno = ?', array($idmes, $anno))
                ->fetchOne()
                ->cantidad;
    }

    public static function obtenerDiasHabiles($idmes, $anno){
        return Doctrine_Query::create()
            -> select('cantdias as diashabiles')
            -> from('ConfCalendarioSNC')
            -> where('idmes = ? and anno = ?', array($idmes, $anno))
            ->fetchOne()
            ->diashabiles;
    }

    public static function obtenerArrCantidadDias($idmes, $anno){
         return Doctrine_Query::create()
            -> select('*')
            -> from('ConfCalendarioSNC')
            -> where('idmes = ? and anno = ?', array($idmes, $anno))
            ->fetchArray();
    }
 
}
